+    int t = (int)blockIdx.x * 256 + (int)threadIdx.x;
+
+    if (b >= B || h >= H || t >= L) return;
+
+    int half = K / 2;
+    int base = (b * H + h) * L;
+
+    float acc = 0.0f;
+    for (int j = 0; j < K; ++j) {
+        int xi = t + j - half;
+        if (xi >= 0 && xi < L) {
+            acc += x[base + xi] * k[h * K + j];
+        }
+    }
+    y[base + t] = acc;
+}
+
+__global__ void dwconv1d_bwd_input_naive(
+    const float* gy,   // [B,H,L]
