+#include <cuda_runtime.h>
+
+extern "C" {
+
+__global__ void dwconv1d_fwd_naive(
+    const float* x,   // [B,H,L]
+    const float* k,   // [H,K]
+    float* y,         // [B,H,L]
+    int B, int H, int L, int K)
+{
+    int b = (int)blockIdx.z;
+    int h = (int)blockIdx.y;
+    int t = (int)blockIdx.x * (int)blockDim.x + (int)threadIdx.x;
+
